#include <stdint.h>
#include <stdio.h>

uint64_t get_le(const unsigned char *b, int size) {
    uint64_t v = 0;
    for (int i = 0; i < size; i++) {
        v |= (uint64_t)b[i] << (8 * i);
    }
    return v;
}

int main(void) {
    int q;
    scanf("%d", &q);
    for (int k = 0; k < q; k++) {
        char type[4];
        scanf("%3s", type);
        int size = type[1] == '1' ? 2 : type[1] == '3' ? 4 : 8;
        unsigned char b[8];
        for (int i = 0; i < size; i++) {
            unsigned value;
            scanf("%x", &value);
            b[i] = (unsigned char)value;
        }
        printf("%llu\n", (unsigned long long)get_le(b, size));
    }
    return 0;
}

